// Flatten GA4 runReport rows into one item per URL.
const out = [];

for (const item of $input.all()) {
  const res = item.json;
  const src = res.__meta || {};
  const rows = res.rows || [];

  for (const r of rows) {
    const d = (r.dimensionValues || []).map(v => v.value);
    const m = (r.metricValues || []).map(v => v.value);
    const pagePath = d[0] || '';
    const host = d[1] || '';
    if (!host) continue;

    out.push({
      json: {
        url: 'https://' + host + pagePath,
        pagePath,
        host,
        pageviews: Number(m[0] || 0),
        users: Number(m[1] || 0),
        engagement_seconds: Math.round(Number(m[2] || 0))
      }
    });
  }
}

if (!out.length) {
  return [{ json: { url: null, note: 'GA4 returned no rows for this period' } }];
}

return out;

// Join GA4 URL metrics onto release_id using the releases tab.
// A release can live on up to 3 URLs; metrics are summed per release.

const norm = (u) => {
  if (!u) return '';
  return String(u).trim().toLowerCase().replace(/[?#].*$/, '').replace(/\/+$/, '');
};

const releases = $('Read releases Tab').all().map(i => i.json);

// Build lookup: normalised URL -> release meta
const lookup = {};
for (const rel of releases) {
  for (const col of ['url_newsroom', 'url_promomag', 'url_choiceformusic']) {
    const key = norm(rel[col]);
    if (key) lookup[key] = rel;
  }
}

const period = $('Config').first().json.period;
const agg = {};

for (const item of $input.all()) {
  const g = item.json;
  if (!g.url) continue;
  const rel = lookup[norm(g.url)];
  if (!rel) continue; // page isn't a tracked release (home, category, etc.)

  const id = rel.release_id;
  if (!agg[id]) {
    agg[id] = {
      release_id: id,
      period,
      title: rel.title || '',
      pageviews: 0,
      users: 0,
      engagement_seconds: 0,
      sites_counted: [],
      pulled_at: new Date().toISOString()
    };
  }
  agg[id].pageviews += g.pageviews;
  agg[id].users += g.users;
  agg[id].engagement_seconds += g.engagement_seconds;
  if (!agg[id].sites_counted.includes(g.host)) agg[id].sites_counted.push(g.host);
}

const rows = Object.values(agg).map(r => ({
  json: {
    ...r,
    sites_counted: r.sites_counted.join(', '),
    avg_engagement_seconds: r.users ? Math.round(r.engagement_seconds / r.users) : 0
  }
}));

if (!rows.length) {
  return [{ json: { release_id: 'NONE', period, note: 'No tracked release URLs matched GA4 data this period' } }];
}

return rows;

const rows = $input.all().map(i => i.json).filter(r => r.release_id && r.release_id !== 'NONE');
const period = $('Config').first().json.period;

if (!rows.length) {
  return [{ json: { text: `PromoBoost analytics ${period}: no tracked releases matched. Check the releases tab URLs.` } }];
}

rows.sort((a, b) => b.pageviews - a.pageviews);

const totalViews = rows.reduce((s, r) => s + r.pageviews, 0);
const totalUsers = rows.reduce((s, r) => s + r.users, 0);

const top = rows.slice(0, 5)
  .map((r, i) => `${i + 1}. ${r.title || r.release_id} — ${r.pageviews} views`)
  .join('\n');

const text = [
  `PromoBoost — ${period}`,
  `${rows.length} releases tracked`,
  `${totalViews} pageviews / ${totalUsers} users`,
  '',
  'Top performers:',
  top
].join('\n');

return [{ json: { text } }];
